record.field:
website = env.ref('toy_store.website_industry')
to_deactivate = [ 'website_sale.carousel_product_indicators_left', 'website_sale.header_hide_empty_wishlist_link', 'website_sale.product_attributes_body', 'website_sale.products_attributes', 'website.footer_custom', 'website.header_call_to_action', 'website.header_search_box', 'website.header_text_element', 'website.header_visibility_standard', 'website.template_header_default', 'website.template_footer_links', 'website.homepage', 'website.contactus', ] to_activate = [ 'website_sale.accept_terms_and_conditions', 'website_sale.accordion_specs_item', 'website_sale.carousel_product_indicators_bottom', 'website_sale.checkout_container_dropzone', 'website_sale.cta_wrapper_boxed', 'website_sale.filmstrip_categories_bordered', 'website_sale.filter_products_price', 'website_sale.product_comment', 'website_sale.product_search', 'website_sale.product_terms_and_conditions', 'website_sale.products_attributes_top', 'website.footer_no_copyright', 'website.header_visibility_fixed', 'website.header_width_full', 'website.template_header_additional_color_primary', 'website.template_header_mobile_position_left', 'website.template_header_sales_one', 'website.template_header_sales_one_align_center', 'portal.user_sign_in', 'website.template_footer_call_to_action', ]
ctx = {'website_id': website.id}
for xml_id in to_deactivate: env.ref(xml_id).with_context(**ctx).write({'active': False}) for xml_id in to_activate: env.ref(xml_id).with_context(**ctx).write({'active': True})

website = env.ref('toy_store.website_industry')
MARK = '__EXPORT_FILTER_XMLID__'
for view in env['ir.ui.view'].sudo().search([('website_id', '=', website.id)]):
    arch = view.arch_db or ''
    if MARK not in arch:
        continue
    new_arch = arch
    while MARK in new_arch:
        start = new_arch.index(MARK)
        end = new_arch.index(MARK, start + len(MARK)) + len(MARK)
        xmlid = new_arch[start + len(MARK):end - len(MARK)]
        try:
            resolved = str(env.ref(xmlid).id)
        except ValueError:
            resolved = '0'
        new_arch = new_arch[:start] + resolved + new_arch[end:]
    view.write({'arch_db': new_arch})
